/* Documentary update 2026-11-10; source facts are dated and do not mutate declared percentages. */
(()=>{
const scriptUrl=document.currentScript.src;
const base=new URL('../documentos/sedam-08352-26/',scriptUrl);
const sources=[["01_sei_77936332_oficio_9687.pdf", "Ofício 9687/2026/SEDAM-GERCON — ID 2057811, 3 páginas"], ["02_10_ata_reuniao_sedam_13_e_14_10_2026_2.pdf", "10ª reunião — 13/10/2026 e complemento de 14/10 — ID 2057812, 2 páginas"], ["03_4_reuniao_acompanhamento_sedam_ata__04_05_2026_ok.pdf", "4ª reunião — 04/05/2026 — ID 2057813, 5 páginas"], ["04_sei_0851385_ata_de_reuniao.pdf", "Alinhamento de 25/04/2025 — SEI 0851385 — ID 2057814, 3 páginas"], ["05_recibo_de_protocolo.pdf", "Recibo de protocolo 08352/26 — ID 2057815, 1 página"], ["06_despacho.pdf", "Despacho de 04/11/2026 — ID 2059374, 1 página"]];
const common="<p class=\"sd-alert\"><strong>Item 3.1 do TAG / ação 45: proposta encaminhada para análise técnica.</strong> O despacho de 04/11/2026 encaminhou o Documento 08352/26 à SGCE/CECEX-09 para juntada ao PCe 04340/25 e análise. Os documentos enviados não contêm decisão aprovando a alteração, nem comprovação de implementação integral. A redação proposta não substitui automaticamente a obrigação pactuada.</p>\n<p><strong>Referências:</strong> TAG — PCe 01702/22 e monitoramento PCe 04340/25; Acórdão APL-TC 00170/25; SEI SEDAM 0028.004382/2025-07; SEI TCE 003001/2025. Protocolo 08352/26 de 29/10/2026, às 12:26:19. Ofício assinado em 28/10/2026 por Ester dos Santos Dourado Silva e Hueriqui Charles Lopes Pereira. Relator do despacho: Francisco Carvalho da Silva.</p>\n<details open><summary>Histórico e tramitação</summary><ol>\n<li><strong>25/04/2025:</strong> alinhamento conjunto SEDAM/SEPAT no TCE-RO, sob presidência de Francisco Júnior Ferreira da Silva. Discussão sobre competências, cooperação, georreferenciamento e aperfeiçoamento do item 3.1; sugestões de grupo de trabalho, norma de fiscalização remota e termo de cooperação para apoio logístico em desocupações. Não equivale à formalização dos instrumentos sugeridos. Fonte: ata SEI 0851385, p. 1–3.</li>\n<li><strong>04/05/2026:</strong> 4ª reunião registra avanços de cooperação e necessidade de formalização e evidências. Os indicadores apresentados são preliminares. Fonte: 4ª ata, p. 1–3.</li>\n<li><strong>13/10/2026, 10h57–11h50 (RO):</strong> reunião remota com Manoel Fernandes Neto (coordenador), Maria Gleidivana Alves de Albuquerque (supervisora) e Hueriqui Charles Lopes Pereira. Pauta: evidências, relatório de execução e item 3.1/ação 45. Fonte: 10ª ata, p. 1–2.</li>\n<li><strong>14/10/2026:</strong> complemento da ata registra sugestão de submissão de proposta fundamentada ao relator temático Francisco Carvalho da Silva. A SEDAM formula e fundamenta a proposta; a equipe de monitoramento realiza exame técnico; o relator delibera. Fonte: 10ª ata, p. 2.</li>\n<li><strong>28–29/10/2026:</strong> assinatura do Ofício 9687 e protocolo do conjunto documental. O ofício também referencia os Ofícios 2209/2025/CPO, 2762/2025/CPO e 4150/2026/GERCON, este protocolado sob 04516/26; esses expedientes anteriores não foram enviados integralmente neste conjunto.</li>\n<li><strong>04/11/2026:</strong> despacho do relator determina encaminhamento à unidade técnica para juntada e análise. Não comprova que a juntada ou a análise já tenham sido concluídas. Fonte: despacho, p. 1.</li></ol></details>\n<details><summary>Item 3.1: obrigação original e proposta apresentada</summary>\n<h4>Redação original transcrita no Ofício 9687 (p. 2)</h4><blockquote>3.1. Firmar parceria interinstitucional entre Sedam, Sepat, TCE/RO e MPE/RO para o estabelecimento de acordo visando maior celeridade e efetividade nas ações voltadas à prevenção e repreensão de atos atentatórios ao meio ambiente, incluindo-se aí ações voltadas à desocupação de unidades de conservação.</blockquote>\n<h4>Redação proposta pela SEDAM — pendente de apreciação</h4><blockquote>3.1. Estruturar e implementar mecanismo de integração interinstitucional, mediante a articulação entre a SEDAM, a SEPAT, CTE/RO, MPE/RO, órgãos de segurança pública e órgãos do Poder Judiciário, com vistas ao compartilhamento de informações e tecnologias, ao estabelecimento de fluxos de comunicação e encaminhamento de ocorrências e à adoção tempestiva das providências cabíveis para a prevenção e repressão de ilícitos ambientais, inclusive aqueles relacionados à ocupação irregular de unidades de conservação, observadas as atribuições legais de cada instituição.</blockquote>\n<p>A sigla “CTE/RO” consta assim no texto proposto do ofício; foi preservada na transcrição. A identificação institucional no painel é TCE-RO. A ata de maio também usa subitens 3.1–3.3 para planejamento estratégico: essa numeração não deve ser confundida com o item 3.1 do TAG/ação 45.</p>\n<h4>Solicitações do ofício (p. 3)</h4><ol><li>Apreciar a redação proposta à luz do histórico e da finalidade discutida em 25/04/2025.</li><li>Avaliar a redefinição dos órgãos participantes conforme suas competências.</li><li>Manifestar-se sobre o uso do PROTEGE, mediante adequações técnicas.</li><li>Definir ou validar produtos, responsáveis, prazos e evidências necessários à aferição.</li><li>Formalizar a deliberação para orientar as providências seguintes.</li></ol></details>\n<details><summary>PROTEGE, integração e unidades de conservação</summary><p>Segundo o Ofício 9687 (p. 2), o PROTEGE é desenvolvido e mantido pela SEDAM e reúne monitoramento ambiental e informações geoespaciais. Seu uso na integração proposta exige avaliação de funcionalidades, interoperabilidade, adequações e compartilhamento. Não há, neste conjunto, prova de integração operacional completa entre os órgãos.</p><p>A ata de 25/04/2025 (p. 2–3) descreve o PROTEGE ainda em implantação, com previsão de alertas de desmatamento, queimadas e sobreposição de CAR; discussão de integração com o sistema móvel da PM, fiscalização remota e presencial, e fluxos para encaminhamento aos órgãos competentes. São registros daquela data, não comprovação da situação atual.</p><p>Em desocupações, a ata registra apoio técnico e logístico da SEDAM e atuação da autoridade judicial e forças policiais conforme suas competências. A proposta de outubro reafirma a observância das atribuições legais e procedimentos aplicáveis.</p></details>";
const sedam="<details><summary>Indicadores históricos e entregas: datas e limites de comprovação</summary><div class=\"sd-scroll\"><table><thead><tr><th>Referência</th><th>Informação registrada</th><th>Tratamento no acompanhamento</th></tr></thead><tbody>\n<tr><td>4ª ata, maio/2026, p. 1</td><td>Percentual geral: abril 33% → maio 51%; 41 subitens declarados com 100%.</td><td>Histórico de maio, preliminar e sujeito à validação; não representa percentual atual de novembro.</td></tr>\n<tr><td>4ª ata, p. 2</td><td>1.1–1.4 e planejamento estratégico 2025–2029 (subitens 3.1–3.3): 100%; processos: entre 80% e 100%; sistemas 6.1–6.4 e Geoportal 9.1–9.4: 100%; transparência 10.1–10.7: 100%.</td><td>Percentuais registrados na reunião; exigem evidências. Não comprovam, isoladamente, cumprimento do item 3.1/ação 45.</td></tr>\n<tr><td>4ª ata, p. 2–3</td><td>Normativos de sensoriamento remoto 7.1–7.2: 75%; comissão/metodologia dos planos de manejo 17.2: 100%; elaboração integral dos planos e ações de campo pendentes.</td><td>Preservar distinção entre comissão constituída e planos concluídos.</td></tr>\n<tr><td>4ª ata, p. 3</td><td>21.1: plano de remoção de semoventes informado como elaborado, em consolidação operacional; parcerias com Exército com tratativas ainda pendentes.</td><td>Solicitar documentos e execução efetiva; não atribuir percentual novo sem suporte.</td></tr>\n<tr><td>10ª ata, p. 1</td><td>21 parcelas georreferenciadas e certificadas de 31, segundo Hueriqui; minuta PPAOF/RO 202X–20XX, sujeita à consulta pública do edital.</td><td>21/31 = 67,74% por cálculo aritmético sobre a quantidade declarada; não equivale à execução global do TAG. Minuta é produto parcial; período definitivo não informado.</td></tr></tbody></table></div></details>\n<details><summary>Evidências, relatório de execução e pendências</summary><ul><li>SEDAM/coordenadores: disponibilizar produtos específicos por item e subitem nas pastas compartilhadas e identificar as pastas com documentos.</li><li>SEDAM: disponibilizar minuta PPAOF/RO como produto parcial e comprovações das 21 parcelas georreferenciadas e certificadas.</li><li>TCE-RO: juntada das evidências disponibilizadas ao PCe 04340/25, conforme encaminhamento da reunião; conclusão da juntada não demonstrada pelos anexos.</li><li>SEDAM informou previsão de consolidar e encaminhar relatório à CGE em novembro/2026, antes do envio ao Tribunal. Não foi fixado dia nem comprovado o envio neste conjunto.</li><li>Classificações previstas para a análise: implementadas, parcialmente implementadas, em implementação, não implementadas e não mais aplicáveis. Classificação técnica depende do exame das evidências.</li><li>Manter em acompanhamento a análise da proposta do item 3.1, eventual deliberação, instrumentos de cooperação, fluxos, responsáveis, produtos, prazos e critérios de comprovação. Não há novo prazo aprovado para o item nos anexos.</li><li>A reunião de 01/06/2026 às 9h foi prevista na 4ª ata; este conjunto não comprova sua realização. O prazo de 30 dias para relatório situacional da SEPAT pertence à ata de 25/04/2025, sem comprovação de cumprimento neste conjunto.</li></ul></details>\n<details><summary>Georreferenciamento: contexto de 25/04/2025</summary><p>A ata SEI 0851385 (p. 1–2) registra atuação integrada SEDAM/SEPAT, convênios com Exército e BNDES e prioridade de Rio Pardo. Menciona sete unidades prioritárias (nomeando Guajará-Mirim, Rio Madeira B, Rio Machado, Samuel e Rio Pardo), oito unidades inicialmente previstas para atuação do Exército e lista de 28 unidades em ordem de prioridade. São recortes distintos do planejamento; não devem ser somados nem confundidos com as 31 parcelas informadas em outubro.</p><p>Encaminhamentos: relatório situacional consolidado pela SEPAT com apoio técnico do TCE, previsto em 30 dias; planejamento consolidado de georreferenciamento pela SEDAM; articulação com órgãos estaduais e federais. A ata não comprova a execução posterior dessas entregas.</p></details>";
const queimadas="<p class=\"sd-alert\"><strong>Vínculo com Queimadas:</strong> registro de governança e prevenção de ilícitos ambientais oriundo do TAG SEDAM. O protocolo pertence ao PCe 04340/25; estes documentos não demonstram juntada ao processo de Queimadas PCe 0501/2026.</p><details open><summary>Repercussões para o acompanhamento de Queimadas</summary><ul><li><strong>Integração institucional:</strong> acompanhar a análise do item 3.1/ação 45 e eventual decisão; só então registrar os produtos, responsáveis e prazos efetivamente aprovados.</li><li><strong>Alertas e resposta:</strong> verificar, mediante evidências futuras, a capacidade do PROTEGE para identificar ocorrências, compartilhar dados, acionar órgãos e acompanhar providências. Interoperabilidade ainda depende de avaliação técnica segundo o ofício.</li><li><strong>Fiscalização remota:</strong> acompanhar normatização e fluxos de fiscalização remota/presencial. Os 75% dos subitens 7.1–7.2 são informação histórica de maio/2026, sujeita à validação.</li><li><strong>Unidades de conservação:</strong> relacionar territorialmente monitoramento e prevenção com planos de manejo, georreferenciamento, regularização e cooperação operacional, sem presumir conclusão das medidas.</li><li><strong>Evidências a conferir:</strong> instrumentos formalizados, fluxos aprovados, definição de competências, documentação técnica de integração, registros de alertas e providências e indicadores efetivamente definidos. Esta lista organiza a análise; não cria obrigação ou prazo novo para a gestão.</li></ul></details><p><strong>Focos de calor:</strong> nenhum dos seis anexos apresenta série mensal ou nova contagem de focos em 2026. Esta atualização documental não altera totais, rankings, mapas ou estatísticas INPE/MAPBIOMAS/PRODES.</p>";
const style="<style>.sd-doc{background:#fff;color:#172b39;border:1px solid #cbd9d2;border-radius:18px;padding:22px;margin:18px 0;font:15px/1.65 system-ui,sans-serif}.sd-doc h2{font-size:22px;color:#14583f;margin:0 0 8px}.sd-doc h4{font-size:16px;margin:14px 0 5px}.sd-doc p,.sd-doc ul,.sd-doc ol{margin:12px 0}.sd-doc li{margin:7px 0}.sd-doc ul,.sd-doc ol{padding-left:24px;list-style:revert}.sd-doc details{border-top:1px solid #dce5df;padding:14px 0}.sd-doc summary{cursor:pointer;font-weight:700;color:#14583f}.sd-doc .sd-alert{background:#fff5d8;border-left:5px solid #c98c12;padding:14px}.sd-doc blockquote{border-left:4px solid #578a74;background:#f3f7f5;padding:12px;margin:12px 0}.sd-doc table{border-collapse:collapse;width:100%;min-width:620px}.sd-doc th,.sd-doc td{border:1px solid #d4dfd8;padding:10px;text-align:left;vertical-align:top}.sd-doc th{background:#edf5ef}.sd-scroll{overflow:auto}.sd-doc a{color:#165ca3;text-decoration:underline}.sd-doc small{color:#52655a}@media print{.sd-doc details>*{display:block!important}.sd-doc{break-inside:auto}}</style>";
function render(){document.querySelectorAll('[data-sedam-documentos]').forEach(host=>{if(host.dataset.rendered)return;host.dataset.rendered='true';const isFire=host.dataset.sedamDocumentos==='queimadas';host.innerHTML=style+'<article class="sd-doc"><h2>'+ (isFire?'SEDAM • Integração e prevenção de ilícitos ambientais':'TAG SEDAM • Atualização documental')+'</h2><small>Conferência documental: 10/11/2026 • Último ato deste conjunto: despacho de 04/11/2026</small>'+ (isFire?queimadas:'')+common+(isFire?'':sedam)+'<details><summary>Documentos de origem — consultar os seis anexos</summary><ul>'+sources.map(([path,label])=>'<li><a target="_blank" rel="noopener" href="'+new URL(path,base).href+'">'+label+'</a></li>').join('')+'</ul><p>Os IDs permitem conferência no <a target="_blank" rel="noopener" href="https://www.tce.ro.gov.br/validardoc">validador do TCE-RO</a>. Datas de reuniões, assinaturas, protocolo e despacho são eventos distintos.</p></details></article>';});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',render);else render();
})();
